idyHeap(){}//----------------------------------------------------------------------------------------// TApplicationTidyHeap::DoMakeDocument//----------------------------------------------------------------------------------------TDocument* TApplicationTidyHeap::DoMakeDocument(CommandNumber /* itsCommandNumber */,														TFile* itsFile) // Override {	TDocument* outPtr = NULL;	OSErr err = itsFile->OpenDataFork();		if(!err)	{		short version;				long count = sizeof(short);				if(!err)			err = itsFile->ReadData(&version, count);				if(!err)		{			switch(version)			{				case 5:					outPtr = new TDocumentTidyHeap5(itsFile);					break;									default:					outPtr = new TDocumentTidyHeap(itsFile);					break;			}		}				itsFile->CloseDataFork();	}		return outPtr;} // TApplicationTidyHeap::DoMakeDocument //----------------------------------------------------------------------------------------// TApplicationTidyHeap::DoMenuCommand//----------------------------------------------------------------------------------------void TApplicationTidyHeap::DoMenuCommand(CommandNumber aCommandNumber) // Override {	switch (aCommandNumber) 	{		default:			Inherited::DoMenuCommand(aCommandNumber);			break;	}} // TApplicationTidyHeap::DoMenuCommand //----------------------------------------------------------------------------------------// TApplicationTidyHeap::DoSetupMenus//----------------------------------------------------------------------------------------void TApplicationTidyHeap::DoSetupMenus() // Override {	Inherited::DoSetupMenus();				// Always call the inherited method first	Enable(cNew,FALSE);	Enable(cSaveAs, FALSE);	} // TApplicationTidyHeap::DoSetupMenus //----------------------------------------------------------------------------------------// TApplicationTidyHeap::DoAboutBox//----------------------------------------------------------------------------------------void TApplicationTidyHeap::DoAboutBox(){	TWindow* window = TViewServer::fgViewServer->NewTemplateWindow(kAboutWindowID, NULL);	::ThrowIfNULL_AC(window);	::SysBeep(30);	window->PoseModally();	window->Close();}//----------------------------------------------------------------------------------------// TApplicationTidyHeap::DoMakeFile: //----------------------------------------------------------------------------------------TFile* TApplicationTidyHeap::DoMakeFile(CommandNumber){	return NewFile(kFileType, kSignature, true, noResourceFork, false, false);}